// Normalises the call, applies defaults and builds the first Anthropic request.
// Everything the retry loop needs travels in the item, so the HTTP node stays dumb.
const ANTHROPIC_URL = 'https://api.anthropic.com/v1/messages';
const DEFAULT_MODEL = 'claude-sonnet-4-5';
const DEFAULT_MAX_RETRIES = 2;
const MAX_TOKENS = 2000;

const input = $input.first().json || {};

const user = String(input.user || '').trim();
if (!user) throw new Error('user prompt is required');

const schema = input.schema;
if (!schema || typeof schema !== 'object') throw new Error('schema is required and must be an object');

const model = String(input.model || DEFAULT_MODEL);
const maxRetries = Number.isInteger(input.max_retries) ? input.max_retries : DEFAULT_MAX_RETRIES;
if (maxRetries < 0 || maxRetries > 5) throw new Error('max_retries must be between 0 and 5');

// The schema is part of the instruction, not a hope: the model is told the exact shape
// and told to answer with JSON only.
const system = [
  String(input.system || '').trim(),
  'Answer with a single JSON object and nothing else. No prose, no code fences.',
  'The object must match this JSON schema:',
  JSON.stringify(schema),
].filter(Boolean).join('\n\n');

// Spend reporting. Workflow 12a is the ledger every model call in this library is meant to
// appear in; until now only the callers that remembered to log reached it, so the daily cap
// was counting a fraction of the spend. The call is logged here instead, once, at the only
// place that sees every caller. A caller that sums a whole batch itself opts out with
// log_spend: false rather than being counted twice.
const logSpend = input.log_spend !== false;
const workflowName = String(input.workflow_name || input.caller || '').trim()
  || '[03] (caller not named)';
const purpose = input.purpose === undefined || input.purpose === null
  ? 'schema call'
  : String(input.purpose).slice(0, 500);

return [{
  json: {
    url: ANTHROPIC_URL,
    model,
    logSpend,
    workflowName,
    purpose,
    schema,
    maxRetries,
    attempt: 0,
    waitSeconds: 2,
    system,
    messages: [{ role: 'user', content: user }],
    body: {
      model,
      max_tokens: MAX_TOKENS,
      system,
      messages: [{ role: 'user', content: user }],
    },
  },
}];

// Parses the reply, validates it against the schema and decides retry or stop.
// This node is the loop controller: on failure it rebuilds the request with the
// validation error appended, so the next pass is a repair attempt, not a repeat.

// A deliberately small JSON Schema subset: type, required, properties, enum, items.
// Enough for the shapes this library asks for, and honest about what it does not cover.
function validate(value, schema, path) {
  const errors = [];
  const p = path || 'root';
  const type = schema.type;

  if (type) {
    const actual = Array.isArray(value) ? 'array' : value === null ? 'null' : typeof value;
    const ok = type === 'integer'
      ? Number.isInteger(value)
      : type === 'number' ? typeof value === 'number' : actual === type;
    if (!ok) {
      errors.push(p + ': expected ' + type + ', got ' + actual);
      return errors;
    }
  }
  if (Array.isArray(schema.enum) && !schema.enum.includes(value)) {
    errors.push(p + ': value ' + JSON.stringify(value) + ' is not one of ' + JSON.stringify(schema.enum));
  }
  if (type === 'object' || schema.properties) {
    for (const key of schema.required || []) {
      if (value === null || typeof value !== 'object' || !(key in value)) {
        errors.push(p + ': missing required property "' + key + '"');
      }
    }
    for (const [key, sub] of Object.entries(schema.properties || {})) {
      if (value && typeof value === 'object' && key in value) {
        errors.push(...validate(value[key], sub, p + '.' + key));
      }
    }
  }
  if (type === 'array' && schema.items && Array.isArray(value)) {
    value.forEach((v, i) => errors.push(...validate(v, schema.items, p + '[' + i + ']')));
  }
  return errors;
}

// Models wrap JSON in prose or fences often enough that this has to be handled.
function extractJson(text) {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  const candidate = fenced ? fenced[1] : text;
  try { return { value: JSON.parse(candidate.trim()) }; } catch (e) { /* fall through */ }
  const start = candidate.search(/[{[]/);
  if (start === -1) return { error: 'no JSON found in the reply' };
  const end = Math.max(candidate.lastIndexOf('}'), candidate.lastIndexOf(']'));
  if (end <= start) return { error: 'no JSON found in the reply' };
  try { return { value: JSON.parse(candidate.slice(start, end + 1)) }; }
  catch (e) { return { error: 'reply is not valid JSON: ' + e.message }; }
}

const state = $('Prepare request').first().json;
const response = $input.first().json || {};
// The attempt number is this node's own run number. It cannot be carried in the item:
// "Prepare request" runs once, so on a retry it hands back attempt 0 again, `done` would
// never turn true, and the loop would keep calling the model until something else stopped
// it. $runIndex is the one counter that actually advances with the loop.
const attempt = $runIndex + 1;

// The HTTP node continues on error, so an API failure arrives here as data.
const apiError = response.error
  ? (typeof response.error === 'string' ? response.error : JSON.stringify(response.error)).slice(0, 300)
  : null;

const text = Array.isArray(response.content)
  ? response.content.filter((c) => c.type === 'text').map((c) => c.text).join('')
  : '';

// Every attempt was paid for, so the usage reported out of here is the sum over all of
// them. The earlier runs of the HTTP node are the only place that history still exists.
let totalIn = 0;
let totalOut = 0;
let counted = 0;
for (let run = 0; run <= $runIndex; run++) {
  let u = null;
  try { u = (($('Call Anthropic').all(0, run)[0] || {}).json || {}).usage; } catch (e) { u = null; }
  if (u) {
    totalIn += Number(u.input_tokens) || 0;
    totalOut += Number(u.output_tokens) || 0;
    counted += 1;
  }
}
const usage = counted ? { input_tokens: totalIn, output_tokens: totalOut } : null;

let data = null;
let errors = [];
if (apiError) {
  errors = ['api call failed: ' + apiError];
} else if (!text) {
  errors = ['empty reply from the model'];
} else {
  const parsed = extractJson(text);
  if (parsed.error) errors = [parsed.error];
  else {
    data = parsed.value;
    errors = validate(data, state.schema, 'root');
  }
}

const ok = errors.length === 0;
const attemptsLeft = state.maxRetries - (attempt - 1);
const done = ok || attemptsLeft <= 0;

// Feed the failure back into the conversation so the retry is a repair.
const messages = ok ? state.messages : [
  ...state.messages,
  { role: 'assistant', content: text || '(no reply)' },
  { role: 'user', content: 'That reply was rejected:\n' + errors.map((e) => '- ' + e).join('\n')
      + '\nAnswer again with a single JSON object matching the schema, nothing else.' },
];

return [{
  json: {
    ...state,
    attempt,
    done,
    ok,
    data: ok ? data : null,
    errors,
    usage,
    raw: text,
    waitSeconds: attempt === 1 ? 2 : 8,
    messages,
    body: { model: state.model, max_tokens: 2000, system: state.system, messages },
  },
}];

// Single exit point, same shape whether the call succeeded or ran out of attempts.
// The state is read from the validator by name, not from the input: the spend log sits
// between the two now, and its answer must never become this workflow's answer.
const s = $('Validate against schema').first().json;
return [{
  json: {
    ok: s.ok,
    data: s.data,
    attempts: s.attempt,
    errors: s.errors,
    usage: s.usage,
    model: s.model,
    raw_on_failure: s.ok ? null : String(s.raw || '').slice(0, 2000),
  },
}];

// The ledger row for this call: the tokens of every attempt, under the caller's name.
const s = $('Validate against schema').first().json;
const u = s.usage || {};
return [{
  json: {
    mode: 'log',
    workflow_name: s.workflowName,
    model: s.model,
    // Whole numbers only: workflow 12a rejects anything else, and a rejected log would
    // take down a model call that already succeeded.
    usage: {
      input_tokens: Math.max(0, Math.round(Number(u.input_tokens) || 0)),
      output_tokens: Math.max(0, Math.round(Number(u.output_tokens) || 0)),
    },
    purpose: s.ok
      ? s.purpose
      : s.purpose + ' (no valid answer after ' + s.attempt + ' attempts)',
  },
}];
